import { BarChart } from "march/charts"
import { Button } from "march/ui"

// sınıfın meyve oylaması: her düğme kendi meyvesine bir oy ekler, çubuk yaylanarak uzar
const FRUITS = ["🍎 Elma", "🍌 Muz", "🍓 Çilek", "🍉 Karpuz"]

export function FruitVote() {
  let $votes = [4, 2, 6, 3]
  const vote = (i: number) => { $votes = $votes.map((v, j) => (j === i ? v + 1 : v)) }
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 2 }}>
      {FRUITS.map((f, i) => <Button size="sm" variant="secondary" on:click={() => vote(i)}>{f}</Button>)}
    </div>
    <BarChart data={() => FRUITS.map((meyve, i) => ({ meyve, oy: $votes[i] }))} x="meyve" y="oy" series="Oy" animate legend={false} title="Meyve oylaması" height={220} />
  </div>
}

import { BarChart } from "march/charts"
import { Card, Segmented, Toggle } from "march/ui"

// mağaza zincirinin şube satışları: çeyrek seçilir, dükkân ve çevrimiçi yan yana ya da üst üste
const BRANCHES = ["Kadıköy", "Beşiktaş", "Çankaya", "Alsancak", "Nilüfer"]
const sales = (q: number) => BRANCHES.map((sube, i) => ({ sube, dukkan: 180 + ((i * 53 + q * 37) % 9) * 40, online: 90 + ((i * 29 + q * 41) % 7) * 35 }))

export function StoreSales() {
  let $q = "1"
  let $stacked = false
  return <Card title="Şube satışları (bin ₺)" actions={[<Segmented size="sm" bind:value={$q} aria-label="Çeyrek" options={["1", "2", "3", "4"].map((q) => ({ value: q, label: `${q}. çeyrek` }))} />]}>
    <Toggle bind:value={$stacked} label="Üst üste göster" />
    <BarChart data={() => sales(Number($q))} x="sube" y={["dukkan", "online"]} series={{ dukkan: "Dükkân", online: "Çevrimiçi" }}
      stacked={$stacked} horizontal animate="out" format={(v: number) => `₺${v} B`} title="Şube satışları" height={260} />
  </Card>
}

import { BarChart } from "march/charts"
import { Button, Card } from "march/ui"

// BarChart'ın bütün özellikleri: data (sinyal), x, y (liste ve getter), series, horizontal, orientation, stacked,
// xFormat, format, yMin, yMax, grid, xLabel, tooltip, onSelect, animate, title, description, empty, legend, class,
// colors, width, height
const MONTHS = ["Oca", "Şub", "Mar", "Nis", "May", "Haz"]
const make = (k: number) => MONTHS.map((ay, i) => ({ ay, yeni: 20 + ((i * 7 + k * 5) % 9) * 6, eski: 30 + ((i * 3 + k * 7) % 8) * 5 }))

export function BarChartLab() {
  let $k = 1
  let $picked = "—"
  let $empty = false
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button class="lab-next" size="sm" on:click={() => { $k++ }}>Yeni veri</Button>
      <Button class="lab-empty" size="sm" variant="ghost" on:click={() => { $empty = !$empty }}>Boşalt / geri getir</Button>
      <span class="lab-picked">Seçilen: {() => $picked}</span>
    </div>
    <BarChart class="lab-bars" data={() => ($empty ? [] : make($k))} x="ay" xFormat={(m: string) => m.toUpperCase()} xLabel="Ay"
      y={["yeni", (r: { eski: number }) => r.eski]} series={["Yeni üye", "Eski üye"]} format={(v: number) => `${v} kişi`}
      yMin={0} yMax={100} grid animate="spring-wobbly" legend="bottom" colors={["#f2801f", "#2f6fed"]}
      tooltip={(p: { x: unknown; y?: number | null; label?: unknown }) => `${p.x}: ${p.y} kişi`} onSelect={(p: { x: unknown; y?: number | null; label?: unknown }) => { $picked = `${p.x} · ${p.y}` }}
      title="Üye artışı" description="Ay ay yeni ve eski üyeler" empty="Henüz veri yok" height={240} />
    <Card m:theme="night">
      <BarChart class="lab-stack" data={() => make($k)} x="ay" y={["yeni", "eski"]} stacked orientation="horizontal" grid={false} legend={false}
        width={320} height={200} title="Yığılmış, yatay" />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { BarChartLab } from "./BarChartLab.tsx"

// BarChartLab'in testleri: kaydedince Testler sekmesinde çalışır
test("altı ay iki seri: on iki çubuk, başlık ve açıklama", () => {
  const s = renderTest(() => <BarChartLab />)
  const chart = s.get(".lab-bars")!
  expect(chart.querySelectorAll(".m-chart-bar").length).toBe(12)
  expect(chart.querySelector("svg title")!.textContent).toBe("Üye artışı")
  expect(chart.querySelector("svg desc")!.textContent).toBe("Ay ay yeni ve eski üyeler")
})

test("bir çubuğa tıklamak onu seçer", async () => {
  const s = renderTest(() => <BarChartLab />)
  s.get(".lab-bars .m-chart-bar")!.dispatchEvent(new MouseEvent("click", { bubbles: true }))
  await s.flush()
  expect(s.get(".lab-picked")!.textContent).toContain("Oca")
})

test("veri boşalınca boş metni görünür", async () => {
  const s = renderTest(() => <BarChartLab />)
  await s.click(".lab-empty")
  expect(s.sees("Henüz veri yok")).toBe(true)
})

test("yığılmış yatay grafik de on iki çubuk çizer", () => {
  const s = renderTest(() => <BarChartLab />)
  expect(s.get(".lab-stack")!.querySelectorAll(".m-chart-bar").length).toBe(12)
})
